import{_ as i,o as t,c as n,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Sign in with GitHub or Google","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sign-in.md","filePath":"guide/sign-in.md"}'),a={name:"guide/sign-in.md"};function s(r,e,h,d,l,g){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="sign-in-with-github-or-google" tabindex="-1">Sign in with GitHub or Google <a class="header-anchor" href="#sign-in-with-github-or-google" aria-label="Permalink to &quot;Sign in with GitHub or Google&quot;">​</a></h1><p>People can sign in to Orbit with GitHub or Google instead of a password. Orbit finds the account whose email the provider has verified, so it never creates an account on its own: someone without one needs an <a href="./members#inviting">invitation</a> first.</p><h2 id="setup" tabindex="-1">Setting it up <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setting it up {#setup}&quot;">​</a></h2><p>Each provider needs an OAuth app of your own. Orbit&#39;s administrator sets it up under <strong>Settings → Sign in with GitHub and Google</strong>, where <strong>Configure</strong> shows the callback URL to register, such as <code>https://orbit.example.com/sign-in/github/callback</code>.</p><ul><li><strong>GitHub:</strong> under GitHub → Settings → Developer settings → OAuth Apps, create a new OAuth app. Use the console&#39;s address as the homepage URL and the callback URL Orbit shows as the authorization callback URL. Copy the client ID, generate a client secret and save both in Orbit.</li><li><strong>Google:</strong> in Google Cloud, under APIs &amp; Services → Credentials, create an OAuth client ID of the <strong>Web application</strong> type and add the callback URL Orbit shows to its authorized redirect URIs. Save the client ID and secret in Orbit. Orbit asks for the <code>openid</code>, <code>email</code> and <code>profile</code> scopes.</li></ul><p>The client secret is stored encrypted and is never shown again; saving without one keeps the one saved before. The callback URL follows <a href="./install#console-address">the console&#39;s address</a>: when that changes, register the new one with the provider.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in {#signing-in}&quot;">​</a></h2><p><strong>Continue with GitHub</strong> and <strong>Continue with Google</strong> appear on the sign-in page once a provider is set up.</p><ul><li>Orbit asks the provider for the emails it has verified, GitHub&#39;s primary email first, and signs in to the account that uses one of them. An email the provider has not verified is never used.</li><li>With <a href="./two-factor">two-factor sign-in</a> on, Orbit asks for the code after the provider, as it does after a password.</li><li>When no account uses those emails, the sign-in stops and says which email it got.</li><li>A sign-in has to finish within 10 minutes, and its link works once.</li></ul><h2 id="invitations" tabindex="-1">Invitations <a class="header-anchor" href="#invitations" aria-label="Permalink to &quot;Invitations {#invitations}&quot;">​</a></h2><p>An invitation can be accepted with <strong>Continue with GitHub</strong> or <strong>Continue with Google</strong> when the provider has verified the invited email. A new member joins without a password and signs in with the provider from then on; someone who already has an account joins with it.</p><h2 id="turning-off" tabindex="-1">Turning it off <a class="header-anchor" href="#turning-off" aria-label="Permalink to &quot;Turning it off {#turning-off}&quot;">​</a></h2><p><strong>Remove</strong> stops signing in with that provider. Sessions that are open stay open and passwords keep working. Members who joined through the provider have no password, so they cannot sign in until the provider is configured again.</p>',13)])])}const p=i(a,[["render",s]]);export{u as __pageData,p as default};
